import fs from 'node:fs';import assert from 'node:assert/strict';
const pages=await(await fetch('http://127.0.0.1:9338/json/list')).json();const ws=new WebSocket(pages.find(p=>p.type==='page').webSocketDebuggerUrl);await new Promise(r=>ws.onopen=r);let serial=0;const pending=new Map(),errors=[];ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id){const c=pending.get(m.id);pending.delete(m.id);if(c)m.error?c.reject(Error(JSON.stringify(m.error))):c.resolve(m.result);}else if(m.method==='Runtime.exceptionThrown')errors.push(m.params.exceptionDetails.text);};const rpc=(method,params={})=>new Promise((resolve,reject)=>{const id=++serial;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}));});const ev=async expression=>{const r=await rpc('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;};let checks=0;const check=(name,v)=>{assert.ok(v,name);checks++;console.log('PASS',name);};const tick=()=>new Promise(r=>setTimeout(r,100));

try {
 await rpc('Runtime.enable');await ev('document.getElementById("wb-more-menu").hidePopover();document.getElementById("wb-drawer-close").click()');
 for(const theme of ['dark','light']) {
  await ev('applyTheme('+JSON.stringify(theme)+')');
  check(theme+' floating menu has translucent blurred material',await ev('(()=>{const s=getComputedStyle(document.getElementById("wb-more-menu"));return s.backdropFilter.includes("blur")&&s.backgroundColor.startsWith("rgba(")&&s.backgroundImage.includes("gradient");})()'));
  await ev('document.getElementById("wb-tasks").click()');check(theme+' task drawer opens with glass material',await ev('!document.getElementById("wb-task-drawer").hidden&&getComputedStyle(document.getElementById("wb-task-drawer")).backdropFilter.includes("blur")'));await ev('document.getElementById("wb-drawer-close").click()');
 }
 const root='D:/santi-console/tools/.qa-toolbar-20261101/project';fs.mkdirSync(root,{recursive:true});fs.writeFileSync(root+'/README.md','# 液态玻璃工作台\n\n这是独立的界面验证目录，不会调用模型。\n\n- 统一材质与边缘高光\n- 保留清晰的阅读对比\n- 文件与任务分层显示\n');
 const response=await fetch('http://127.0.0.1:7811/api/workbench/conversations',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({agent:'codex',cwd:root,title:'液态玻璃界面验证'})});const conversation=await response.json();await ev('workbench.open('+JSON.stringify(conversation.id)+')');await ev('applyTheme("dark");document.getElementById("wb-files").click()');await tick();await tick();check('project file panel browses actual fixture',await ev('!document.getElementById("wb-workspace").hidden&&document.getElementById("wb-file-list").textContent.includes("README.md")'));
 await ev('[...document.querySelectorAll(".wb-file-entry")].find(e=>e.textContent.includes("README.md")).click()');await tick();check('Markdown content remains readable',await ev('document.getElementById("wb-file-preview").textContent.includes("统一材质与边缘高光")'));
 let shot=await rpc('Page.captureScreenshot',{format:'png'});fs.writeFileSync('tools/liquid-glass-workspace-20261101.png',Buffer.from(shot.data,'base64'));
 await ev('document.getElementById("wb-rename").click()');check('rename modal keeps glass and input',await ev('document.getElementById("wb-name-dialog").open&&getComputedStyle(document.getElementById("wb-name-dialog")).backdropFilter.includes("blur")&&document.getElementById("wb-name-input").value==="液态玻璃界面验证"'));await ev('document.getElementById("wb-name-dialog").close()');
 await ev('document.documentElement.dataset.perf="lite"');check('lite mode disables expensive blur',await ev('getComputedStyle(document.getElementById("wb-more-menu")).backdropFilter==="none"'));await ev('document.documentElement.dataset.perf="rich"');
 await rpc('Emulation.setEmulatedMedia',{features:[{name:'prefers-reduced-transparency',value:'reduce'}]});check('reduced transparency has solid fallback',await ev('getComputedStyle(document.getElementById("wb-more-menu")).backdropFilter==="none"'));await rpc('Emulation.setEmulatedMedia',{features:[]});
 await ev('document.getElementById("wb-more-menu").showPopover();document.getElementById("wb-more").blur()');await tick();
 const clip=await ev('(()=>{const r=document.querySelector(".head-right").getBoundingClientRect();return {x:Math.max(0,r.left-20),y:Math.max(0,r.top-12),width:Math.min(innerWidth-r.left+20,r.width+36),height:310,scale:1};})()');shot=await rpc('Page.captureScreenshot',{format:'png',clip});fs.writeFileSync('tools/liquid-glass-toolbar-20261101.png',Buffer.from(shot.data,'base64'));
 check('no runtime exceptions',errors.length===0);check('no model tasks started',await ev('workbench.state.tasks.length===0'));
 fs.writeFileSync('tools/liquid-glass-results-20261101.json',JSON.stringify({passed:true,checks,errors,type:'actual isolated Electron, light/dark, real fixture file preview, keyboard toolbar verified separately; no model calls',date:new Date().toISOString()},null,2));console.log('CHECKS',checks);
}finally{await rpc('Emulation.setEmulatedMedia',{features:[]}).catch(()=>{});ws.close();}
